pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        uint256 delay = 1;

        c.schedule(target, value, data, predecessor, salt, delay);
        vm.warp(block.timestamp + delay);

        bool ok;
        try c.execute(target, value, data, predecessor, salt) { ok = true; } catch { ok = false; }

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        assertTrue(ok && c.isOperationDone(id));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        address[] memory proposers = new address[](0);
        address[] memory executors = new address[](0);
        c = new C(7 days, proposers, executors); 
    }
    function testRegression_property() public {
        // schedule an operation with delay=1 day, which is less than minDelay (7 days)
        // reference should revert, buggy should not
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        uint256 delay = 1 days;

        bool didRevert = false;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // In reference (correct) version, schedule reverts because delay < minDelay
        // In buggy version, schedule succeeds because _minDelay is 0
        assertTrue(didRevert);
    }
}

