pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Grant EXECUTOR_ROLE to address(0) to make the role "open"
        c.grantRole(c.EXECUTOR_ROLE(), address(0));

        // Schedule an operation that will be ready immediately (delay = 0)
        address target = address(0x123);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        vm.warp(block.timestamp + 1); // make the operation ready

        // An account without EXECUTOR_ROLE tries to execute
        address randomUser = address(0x456);
        vm.prank(randomUser);
        bool ok;
        try c.execute(target, value, data, predecessor, salt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference version: succeeds (open role allows anyone)
        // Buggy version: fails (onlyRoleOrOpenRole incorrectly checks role for caller)
        assertTrue(ok);
    }
}

