        bool ok;
        try c.execute{value: 0}(address(0xdead), 0, "", bytes32(0), bytes32(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: open role -> random can execute; buggy: random canNOT -> ok is false
        assertTrue(ok);
    }
}

