        // Now randomUser (without EXECUTOR_ROLE) tries to execute
        vm.prank(randomUser);
        bool ok;
        try c.execute(address(this), 0, emptyData, bytes32(0), salt) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference version, this succeeds because EXECUTOR_ROLE is open (address(0) has it)
        // In the modified version, the modifier checks if address(0) has the role and then requires caller to have it, which randomUser does not
        assertTrue(ok);
    }
}

