import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        address target = address(0x123);
        uint256 value = 0;
        bytes memory data = hex"";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        // Schedule an operation with zero delay (minDelay is 0)
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        // Warp past the timestamp so the operation is ready
        vm.warp(block.timestamp + 1);
        // Execute the operation
        c.execute(target, value, data, predecessor, salt);
        // Now the operation is done (timestamp = _DONE_TIMESTAMP = 1)
        // Try to cancel the operation: in reference, should revert because isOperationPending returns false
        // In buggy version, cancel uses require(!isOperationPending(id), ...) which is negated incorrectly
        bool ok;
        try c.cancel(id) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference version reverts, so ok == false. The buggy version succeeds, so ok == true.
        // Assert that cancel failed (reverted) as in the reference
        assertTrue(!ok);
    }
}
